(() => {
  const assets = {
    hero: 'data:image/jpeg;base64,',
    contact: 'data:image/jpeg;base64,',
    sealWhite: 'data:image/png;base64,',
    sealPink: 'data:image/png;base64,',
    caroll: 'data:image/jpeg;base64,'
  };
  assets.supplierLogos = {
    'casamento zen': 'data:image/jpeg;base64,'
    ,'edi confeitaria': 'data:image/jpeg;base64,'
    ,'marcelly malaquias': 'data:image/png;base64,'
  };
  window.UniversoAssets = assets;
  let contactPieces = null;

  const prepareContactPieces = () => {
    const source = new Image();
    source.onload = () => {
      const cut = (x, y, width, height) => {
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        canvas.getContext('2d').drawImage(source, x, y, width, height, 0, 0, width, height);
        return canvas.toDataURL('image/png');
      };
      contactPieces = {
        instagram: cut(30, 58, 245, 120),
        whatsapp: cut(287, 58, 242, 120)
      };
      apply();
    };
    source.src = assets.contact;
  };

  const apply = () => {
    const hero = document.querySelector('.hero-photo');
    if (hero) {
      hero.style.backgroundImage =
        'linear-gradient(90deg, #72043b 0%, rgba(114,4,59,.78) 22%, rgba(114,4,59,.18) 48%, rgba(114,4,59,0) 72%), url("' + assets.hero + '")';
    }

    document.querySelectorAll('.supplier-card').forEach(card => {
      const name = card.querySelector('h3')?.textContent.trim().toLocaleLowerCase('pt-BR');
      const logo = card.querySelector('.supplier-logo');
      if (!name || !logo) return;

      const supplierLogo = assets.supplierLogos?.[name];
      if (supplierLogo && !logo.querySelector('.supplier-photo')) {
        logo.classList.add('has-photo','has-supplier-logo');
        const photo = document.createElement('img');
        photo.className = 'supplier-photo';
        photo.alt = card.querySelector('h3')?.textContent.trim() || 'Logo do fornecedor';
        photo.src = supplierLogo;
        logo.prepend(photo);
      }

      if (name === 'caroll cardozo' && !logo.querySelector('.supplier-photo')) {
        logo.classList.add('has-photo');
        const photo = document.createElement('img');
        photo.className = 'supplier-photo';
        photo.alt = 'Caroll Cardozo';
        photo.src = assets.caroll;
        logo.prepend(photo);
      }

      let seal = logo.querySelector('.supplier-seal');
      if (!seal || seal.tagName !== 'IMG') {
        const old = seal;
        seal = document.createElement('img');
        seal.className = 'supplier-seal';
        seal.alt = 'Parceiro do Universo da Debutante';
        if (old) old.replaceWith(seal); else logo.append(seal);
      }
      const isPink = name === 'assessora bianka temperine' || name === 'caroll cardozo';
      seal.classList.toggle('seal-pink', isPink);
      seal.classList.toggle('seal-white', !isPink);
      seal.src = isPink ? assets.sealPink : assets.sealWhite;

      const contact = card.querySelector('.contact-art img');
      if (contact) {
        contact.src = assets.contact;
        const wrapper = contact.parentElement;
        if (contactPieces && wrapper) {
          wrapper.classList.add('split-art');
          contact.classList.add('contact-source');
          contact.style.display = 'none';
          ['instagram', 'whatsapp'].forEach(kind => {
            const button = wrapper.querySelector('.social-button.' + kind);
            if (button && !button.querySelector('.contact-piece')) {
              const piece = document.createElement('img');
              piece.className = 'contact-piece';
              piece.alt = '';
              piece.src = contactPieces[kind];
              button.append(piece);
            }
          });
        }
      }
    });
  };

  const start = () => {
    apply();
    prepareContactPieces();
    const grid = document.querySelector('#supplierGrid');
    if (grid) new MutationObserver(apply).observe(grid, {childList:true, subtree:true});
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
